import{_ as e,c as a,o as r,ag as n}from"./chunks/framework.Ci10AEOF.js";const p=JSON.parse('{"title":"Glossary","description":"Key terms used across the OIE documentation, with the engine behavior behind each one","frontmatter":{"title":"Glossary","description":"Key terms used across the OIE documentation, with the engine behavior behind each one"},"headers":[],"relativePath":"engine/glossary.md","filePath":"engine/glossary.md","lastUpdated":1793057853000}'),s={name:"engine/glossary.md"};function o(d,t,i,c,l,g){return r(),a("div",null,t[0]||(t[0]=[n('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Term</th><th>Definition</th></tr></thead><tbody><tr><td><a id="ack"></a><strong>ACK</strong></td><td>Acknowledgment message sent back to a sender confirming receipt of a message (common in HL7)</td></tr><tr><td><a id="attachment"></a><strong>Attachment</strong></td><td>Content stored with a message but apart from its body. The attachment handler extracts attachments as a message arrives, and a script can add or update them later. See <a href="./message_lifecycle.html#attachments">Attachments</a></td></tr><tr><td><a id="batch"></a><strong>Batch</strong></td><td>A single inbound payload that is split into multiple messages</td></tr><tr><td><a id="channel"></a><strong>Channel</strong></td><td>The unit of integration in OIE: one source connector and one or more destinations, each with its own filter and transformer, plus the channel scripts. Cloverleaf and Rhapsody users may know the same idea as an interface or a route</td></tr><tr><td><a id="channel-group"></a><strong>Channel Group</strong></td><td>A named group of channels, shown in the Channels view and on the Dashboard</td></tr><tr><td><a id="channel-map"></a><strong>Channel Map</strong></td><td>A key-value store scoped to a single message across all connectors in a channel. Shorthand <code>$c</code>. Read-only in the postprocessor</td></tr><tr><td><a id="channel-writer-reader"></a><strong>Channel Writer/Reader</strong></td><td>Internal connectors for routing messages between channels within the same OIE instance</td></tr><tr><td><a id="code-template"></a><strong>Code Template</strong></td><td>A reusable JavaScript function or code snippet shared across channels</td></tr><tr><td><a id="configuration-map"></a><strong>Configuration Map</strong></td><td>Server-wide key-value pairs accessible in all channel scripts; configured in Settings. Shorthand <code>$cfg</code></td></tr><tr><td><a id="connector"></a><strong>Connector</strong></td><td>The source or a destination of a channel. Its type, such as TCP Listener, File Writer, or JavaScript Writer, decides its settings and what it does</td></tr><tr><td><a id="connector-map"></a><strong>Connector Map</strong></td><td>A key-value store scoped to a single message within a single connector. Shorthand <code>$co</code></td></tr><tr><td><a id="dashboard"></a><strong>Dashboard</strong></td><td>The main operational view showing deployed channels and their real-time statistics</td></tr><tr><td><a id="data-pruner"></a><strong>Data Pruner</strong></td><td>A background process that automatically removes old message data</td></tr><tr><td><a id="data-type"></a><strong>Data Type</strong></td><td>A message format (e.g., HL7 v2.x, XML, JSON, DICOM) and the settings the engine uses to serialize and deserialize it. The data type decides what <code>msg</code> and <code>tmp</code> are: E4X XML for XML-based types, a JavaScript object for JSON, a JavaScript String object for Raw</td></tr><tr><td><a id="deploy"></a><strong>Deploy</strong></td><td>Loading a saved channel definition into the engine. Scripts are compiled, connectors created, tables reconciled, and the channel is then started, paused, or left stopped according to its Initial State. See <a href="./channel_state.html">Deploy, Start, and Channel State</a></td></tr><tr><td><a id="derby"></a><strong>Derby</strong></td><td>Apache Derby; the embedded database used by default for development</td></tr><tr><td><a id="destination"></a><strong>Destination</strong></td><td>A connector that runs after the source, with its own filter and transformer. It usually sends the message somewhere, but need not: a Channel Writer left at None sends nothing. See <a href="./architecture_overview.html#connectors">Connectors</a></td></tr><tr><td><a id="destination-set"></a><strong>Destination Set</strong></td><td>The set of destinations that will process a given message. Available on the source connector only, and modifiable from the source filter or transformer via <code>destinationSet</code></td></tr><tr><td><a id="dicom"></a><strong>DICOM</strong></td><td>Digital Imaging and Communications in Medicine; a standard for medical imaging</td></tr><tr><td><a id="donkey"></a><strong>Donkey</strong></td><td>The internal message processing engine that handles queuing, storage, and message lifecycle</td></tr><tr><td><a id="e4x"></a><strong>E4X</strong></td><td>ECMAScript for XML; the syntax used to access message fields when the data type is XML-based (HL7 v2.x, HL7 v3.x, XML, EDI/X12, NCPDP, Delimited Text, DICOM). JSON and Raw messages are not E4X</td></tr><tr><td><a id="edi"></a><strong>EDI</strong></td><td>Electronic Data Interchange; a standard for business document exchange</td></tr><tr><td><a id="extension"></a><strong>Extension</strong></td><td>An add-on the engine loads at startup, such as a connector, data type, or transformer step. Most built-in features ship as extensions. See <a href="./plugins.html">Plugin Guide</a></td></tr><tr><td><a id="filter"></a><strong>Filter</strong></td><td>A set of rules that determine whether a message should be processed or rejected. Compiled into the same script as its transformer: a variable a rule assigns without <code>var</code> is still there in the transformer, while one declared with <code>var</code> stays inside its rule</td></tr><tr><td><a id="global-channel-map"></a><strong>Global Channel Map</strong></td><td>A key-value store shared across all messages within a specific channel. Shorthand <code>$gc</code>. Held in memory, not stored with messages, and cleared when the channel deploys unless its setting says otherwise. Not present in the global deploy and undeploy scripts</td></tr><tr><td><a id="global-map"></a><strong>Global Map</strong></td><td>A key-value store shared across all channels on the server. Shorthand <code>$g</code>. Held in memory until the server restarts, not stored with messages, and cleared on Redeploy All by default</td></tr><tr><td><a id="hl7"></a><strong>HL7</strong></td><td>Health Level Seven; a set of international standards for healthcare data exchange</td></tr><tr><td><a id="iterator"></a><strong>Iterator</strong></td><td>A transformer step and filter rule type that loops over repeating segments or elements</td></tr><tr><td><a id="mapper"></a><strong>Mapper</strong></td><td>A transformer step type that extracts a value from the source message into a variable</td></tr><tr><td><a id="message"></a><strong>Message</strong></td><td>One unit of data processed by a channel</td></tr><tr><td><a id="message-browser"></a><strong>Message Browser</strong></td><td>The UI for searching, viewing, and managing individual messages. Channel and connector map entries appear on its Mappings tab</td></tr><tr><td><a id="message-builder"></a><strong>Message Builder</strong></td><td>A transformer step type that sets a field in the outbound message</td></tr><tr><td><a id="message-storage-mode"></a><strong>Message Storage Mode</strong></td><td>Controls how much message content is persisted (Development, Production, Raw, Metadata, Disabled)</td></tr><tr><td><a id="mllp"></a><strong>MLLP</strong></td><td>Minimal Lower Layer Protocol; the standard framing protocol for HL7 over TCP</td></tr><tr><td><a id="nack"></a><strong>NACK</strong></td><td>Negative Acknowledgment; indicates a message was received but could not be processed</td></tr><tr><td><a id="ncpdp"></a><strong>NCPDP</strong></td><td>National Council for Prescription Drug Programs; a pharmacy transaction standard</td></tr><tr><td><a id="oie"></a><strong>OIE</strong></td><td>Open Integration Engine; this project</td></tr><tr><td><a id="postprocessor"></a><strong>Postprocessor</strong></td><td>A channel script that runs after all destinations have processed a message. Its source map and channel map are read-only; its response map is writable</td></tr><tr><td><a id="preprocessor"></a><strong>Preprocessor</strong></td><td>A channel script that runs before the source filter and transformer, receiving the raw message as a String in <code>message</code></td></tr><tr><td><a id="pruning"></a><strong>Pruning</strong></td><td>The process of removing old message data from the database</td></tr><tr><td><a id="queue"></a><strong>Queue</strong></td><td>A set of rows in the database, not an in-memory structure: the source queue is this connector&#39;s messages in RECEIVED status, a destination queue is that destination&#39;s messages in QUEUED status. Each keeps a small in-memory buffer filled from that query. See <a href="./queueing.html">Queueing</a></td></tr><tr><td><a id="response"></a><strong>Response</strong></td><td>What a destination got back when it sent a message</td></tr><tr><td><a id="response-map"></a><strong>Response Map</strong></td><td>A key-value store holding each destination&#39;s response under its <code>d</code> key, plus anything a script puts there. The source can return any entry as its response. Shorthand <code>$r</code></td></tr><tr><td><a id="rhino"></a><strong>Rhino</strong></td><td>Mozilla Rhino; the JavaScript engine used by OIE. Language version is set by <code>rhino.languageversion</code> in <code>mirth.properties</code></td></tr><tr><td><a id="rule"></a><strong>Rule</strong></td><td>A single condition within a filter (Rule Builder, JavaScript, External Script, or Iterator)</td></tr><tr><td><a id="serialization"></a><strong>Serialization</strong></td><td>Converting a message from its inbound data type into the internal representation that filters and transformers work with: XML for every built-in data type except JSON and Raw. Deserialization is the reverse, from the internal representation to the outbound data type</td></tr><tr><td><a id="source"></a><strong>Source</strong></td><td>The connector that receives inbound messages for a channel</td></tr><tr><td><a id="source-map"></a><strong>Source Map</strong></td><td>A key-value store populated by the source connector with metadata (e.g., remote address). Shorthand <code>$s</code></td></tr><tr><td><a id="step"></a><strong>Step</strong></td><td>A single operation within a transformer (Mapper, Message Builder, JavaScript, etc.)</td></tr><tr><td><a id="tag"></a><strong>Tag</strong></td><td>A label applied to channels, used to filter them in the Channels view and on the Dashboard</td></tr><tr><td><a id="template"></a><strong>Template</strong></td><td>Either a transformer&#39;s outbound message template, which becomes <code>tmp</code>, or a destination connector&#39;s content field, which supports variable substitution</td></tr><tr><td><a id="transformer"></a><strong>Transformer</strong></td><td>A sequence of steps that modify message content as it passes through a connector</td></tr><tr><td><a id="transmission-mode"></a><strong>Transmission Mode</strong></td><td>The framing protocol used by TCP connectors (MLLP, Basic)</td></tr><tr><td><a id="undeploy"></a><strong>Undeploy</strong></td><td>The reverse of deploy: the channel is stopped, its connectors are undeployed, its undeploy script runs, and the engine unloads it. See <a href="./channel_state.html#undeploy">Undeploy</a></td></tr><tr><td><a id="vm"></a><strong>VM</strong></td><td>The underlying connector protocol for channel-to-channel routing; exposed in the UI as Channel Reader (source) and Channel Writer (destination)</td></tr></tbody></table>',2)]))}const m=e(s,[["render",o]]);export{p as __pageData,m as default};
